  border-radius: 4px;
}

.hours-note p {
  margin-bottom: 0;
}

.contact-section {
  background-color: var(--color-bg);
}

.contact-grid {
  display: grid;
  gap: 3rem;
  grid-template-columns: 1fr 1fr;
  margin-top: 2rem;
}

.contact-info h3 {
  margin-top: 0;
}

.contact-item {
  margin-bottom: 1.5rem;
}

.contact-item p {
  margin-bottom: 0;
  line-height: 1.8;
}

.contact-item strong {
  color: var(--color-primary-dark);
}

.contact-form-wrapper {
  background-color: #f9f9f9;
  padding: 2rem;
  border-radius: 4px;
  border: 1px solid var(--color-border);
}

.contact-form-wrapper h3 {
  margin-top: 0;
}

.contact-form .form-group {
  margin-bottom: 1.25rem;
}

.contact-form label {
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.contact-form input,
.contact-form textarea {
  width: 100%;
}

.contact-form button {
  width: 100%;
  min-height: 48px;
}

.testimonials-section {
  background-color: #f9f9f9;
}

.testimonials-grid {
  display: grid;
  gap: 1.5rem;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  margin-top: 2rem;
}

.testimonial-card {
  background-color: var(--color-text-light);
  padding: 1.5rem;
  border-radius: 4px;
  border-left: 4px solid var(--color-accent);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}

.testimonial-text {
  font-size: 0.95rem;
  font-style: italic;
  margin-bottom: 1rem;
  line-height: 1.7;
  color: var(--color-text);
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0;
  font-size: 0.9rem;
}

@media (max-width: 600px) {
  .hero {
    padding: 2.5rem 0;
  }

  .hero h1 {
    font-size: 2rem;
  }

  .hero-subtitle {
    font-size: 1.2rem;
  }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .hours-grid {
    grid-template-columns: 1fr;
  }

  .contact-form-wrapper {
    padding: 1.5rem;
  }
}

@media (min-width: 601px) {
  .hero {
    padding: 5rem 0;
  }

  .contact-grid {
    grid-template-columns: 1fr 1fr;
  }
}
